<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
$user=app_require_auth();
$canSelf=app_has_permission('timeclock.self',$user);$canView=app_has_permission('timeclock.view',$user);$canManage=app_has_permission('timeclock.manage',$user);$canAttendance=app_has_permission('attendance.view',$user);$canVoice=app_has_permission('voice.self',$user);$canVoiceManage=app_has_permission('voice.manage',$user);$canAgent=app_has_permission('timeclock.agent',$user);$canProactive=app_has_permission('agent.proactive',$user);
if(!$canSelf&&!$canView&&!$canAttendance&&!$canVoice){http_response_code(403);exit('Time Clock permission required.');}
